  function save(){clearTimeout(saveTimer);$('#saving').textContent='正在保存…';saveTimer=setTimeout(persist,160);}
  function fit(){fitFrame=0;for(const el of document.querySelectorAll('[data-fit]')){el.style.fontSize='';const width=el.clientWidth;if(!width)continue;let size=parseFloat(getComputedStyle(el).fontSize);const min=innerWidth<600?10:16;for(let i=0;i<6&&el.scrollWidth>width+1&&size>min;i++){size=Math.max(min,size*width/el.scrollWidth*.983);el.style.fontSize=size+'px';}el.style.overflow='hidden';el.style.textOverflow='ellipsis';}T.fit();}
  function scheduleFit(){if(!fitFrame)fitFrame=requestAnimationFrame(fit);}
  function code(line){const el=E('span','route-code',line.code);el.style.setProperty('--route-color',line.color);return el;}
