  function updateCarsInEditor(id){for(const el of document.querySelectorAll('[data-cars-id]'))if(el.dataset.carsId===id&&el!==document.activeElement)el.value=M.carsFor(state,id);for(const el of document.querySelectorAll('option[data-vehicle-id]'))if(el.dataset.vehicleId===id)el.textContent=vehicleLabel(M.byId.get(id));for(const el of document.querySelectorAll('[data-formation-id]'))if(el.dataset.formationId===id)el.textContent='当前模型 '+M.carsFor(state,id)+' 节 · '+M.byId.get(id).series;}
