    preset.addEventListener('change',()=>{if(preset.value==='__custom__'){customGroup.hidden=false;custom.focus();}else{row.destination=preset.value;row.destinationEn=D.destinations[row.destination]||'';custom.value=row.destination;en.value=row.destinationEn;customGroup.hidden=true;changed(row);}});custom.addEventListener('input',()=>{const value=M.text(custom.value,24).trim();if(value){row.destination=value;row.destinationEn=D.destinations[value]||'';en.value=row.destinationEn;changed(row);}else $('#saving').textContent='行先不可留空，保留上一次有效内容';});en.addEventListener('input',()=>{row.destinationEn=M.text(en.value,70);changed(row);});section.append(field('行先',preset),customGroup,field('行先英文（可留空）',en));
