  THEMES.profiles.forEach(t=>$('#display-theme').append(option(t.id,t.label+' · '+t.station+'参考')));$('#display-theme').addEventListener('change',()=>{state.display.theme=$('#display-theme').value;changed();});
  $('#load-scene').addEventListener('click',()=>{const next=M.scene($('#scene').value);if(!next)return;next.formations=Object.assign({},state.formations);next.timetablePins=Object.assign({},state.timetablePins);next.rows.forEach(r=>TT.selectVehicle(r,next));next.display=Object.assign({},state.display);next.message=state.message;next.ticker=Object.assign({},state.ticker);next.announcements=Object.assign({},state.announcements);A.stop();state=next;changed();renderEditor();toast('已载入四班列车，保留编组与显示设置');});
