  $('#fullscreen').addEventListener('click',async()=>{try{if(document.fullscreenElement&&document.exitFullscreen)await document.exitFullscreen();else if(document.documentElement.requestFullscreen)await document.documentElement.requestFullscreen();else if(document.documentElement.webkitRequestFullscreen)document.documentElement.webkitRequestFullscreen();else toast('Safari：分享 → 添加到主屏幕，可获得独立显示窗口');}catch(_){toast('此浏览器无法全屏，可尝试添加到主屏幕');}});
  async function awake(){if(!awakeRequested)return;if(!('wakeLock'in navigator)){toast('当前浏览器不支持常亮，请调整设备自动锁定设置');$('#keep-awake').checked=false;awakeRequested=false;return;}try{wakeLock=await navigator.wakeLock.request('screen');wakeLock.addEventListener('release',()=>wakeLock=null);}catch(_){toast('未能保持常亮，请检查设备设置');$('#keep-awake').checked=false;awakeRequested=false;}}
  $('#keep-awake').addEventListener('change',async event=>{awakeRequested=event.target.checked;if(awakeRequested)await awake();else if(wakeLock){await wakeLock.release();wakeLock=null;}});document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&awakeRequested&&!wakeLock)awake();});
